    """Extend each bottom-row 5 upward through its column, propagating
    each encountered nonzero color upward until the next nonzero cell."""
    out = [row[:] for row in grid]
    if not grid:
        return out
    last = len(grid) - 1
    for c, value in enumerate(grid[last]):
        if value != 5:
            continue
        carried = 5
        for r in range(last, -1, -1):
            if grid[r][c] != 0:
                carried = grid[r][c]
            else:
                out[r][c] = carried
